// Ensure neighbors are found for the current node
current_node->find_neighbors();

// Iterate through all neighbors of the current node
for (auto* neighbor : current_node->neighbors) {
    // Skip if neighbor has already been visited
    if (neighbor->visited) {
        continue;
    }

    // Calculate tentative g value (distance from start to neighbor through current node)
    float tentative_g = current_node->g_value + current_node->distance(*neighbor);

    // If the tentative g value is better than the neighbor's current g value
    if (tentative_g < neighbor->g_value) {
        // Update neighbor's parent, g_value, and h_value
        neighbor->parent = current_node;
        neighbor->g_value = tentative_g;
        neighbor->h_value = calc_h_value(neighbor);

        // Add neighbor to the open list
        open_list.push_back(neighbor);
    }
}

